<?php
namespace Database\Seeders;
use App\Models\NumberMeaning;
use Illuminate\Database\Seeder;
class EditorialNumberMeaningsGapFixSeeder extends Seeder {
 public function run(): void {
  $entries = [
            ['66', 'Когда забота становится обязанностью', 'Повтор шестёрки в нумерологии усиливает тему дома, ответственности и участия. Но забота перестаёт быть свободным даром, когда человек запрещает себе устать или отказать. Шестьдесят шесть предлагает посмотреть на границу между любовью и обязанностью быть незаменимым.', 'Тёплая поддержка без самоотречения.', 'Контроль над близкими под видом заботы и молчаливая обида за собственные жертвы.', 'Где моя помощь перестала быть добровольной?', 'Выбери одно обязательство и спокойно обсуди, как разделить его с другими.'],
            ['77', 'Глубина без претензии на истину', 'Две семёрки в современной нумерологии усиливают образ исследования, интуиции и духовного поиска. Но сильное внутреннее переживание не становится от этого доказательством универсальной истины. Семьдесят семь напоминает: подлинная глубина допускает сомнение и не требует, чтобы все видели мир одинаково.', 'Внимательное исследование с интеллектуальной скромностью.', 'Убеждённость, что личное озарение даёт право учить других без вопросов.', 'Как отличить то, что я пережил, от того, что я лишь заключил из переживания?', 'Опиши важный внутренний опыт отдельно от объяснений его причины.'],
            ['88', 'Изобилие без зависимости от результата', 'Две восьмёрки традиционно связывают с материальными ресурсами, влиянием и темой обмена. Однако число не обещает богатства: оно может стать напоминанием о цене, которую мы платим за постоянную гонку. Настоящая устойчивость проявляется не только в накоплении, но и в способности распоряжаться имеющимся осмысленно.', 'Ответственное отношение к деньгам и власти, щедрость без демонстрации.', 'Привычка измерять свою ценность доходом, статусом или контролем.', 'Какая часть моего стремления к достатку продиктована страхом оказаться недостаточным?', 'Назови одну материальную цель и запиши, какой человеческой потребности она служит.'],
            ['123', 'Шаги, а не скачок', 'Последовательность 1–2–3 в символическом чтении напоминает о естественном движении: начать, встретиться с реальностью и выразить результат. В ней нет обещания лёгкого пути. Скорее это повод заметить, как часто мы хотим сразу оказаться на третьей ступени, минуя неловкость первых попыток.', 'Терпение к постепенному росту и умение видеть промежуточный результат.', 'Сравнение своего начала с чужим завершённым делом.', 'Какой необходимый первый или второй шаг я пытаюсь перескочить?', 'Разбей важную задачу на три действия и выполни только первое.']
  ];
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
   if (!$record) { continue; }
   $text = (string) $record->symbolism;
   $generated = str_starts_with($text,'Число '.$number.' можно использовать как повод для самонаблюдения.')
    || str_starts_with($text,'Иногда мы замечаем число в тот момент')
    || str_starts_with($text,'Представь это число не как указание судьбы')
    || str_starts_with($text,'Не нужно верить, что совпадение что-то предсказывает')
    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
}
